const COURSE_EXPANSION={"ingles": [{"id": "course-ingles-25", "title": "Uma conversa completa: conhecer alguém", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Uma apresentação precisa de abertura, informação e resposta ao interlocutor. Use be para origem e ocupação e perguntas curtas para manter a conversa. O objetivo é comunicar dados coerentes, não apenas decorar uma saudação. Observe a diferença entre nome e tratamento e evite traduzir idade com have.", "phrase": "Hello, I'm Nina. I'm from Brazil and I'm a student. What about you?", "reading": "", "meaning": "Olá, sou Nina. Sou do Brasil e sou estudante. E você?", "wrong": "Hello, I is Nina. I from Brazil and I a student.", "task": "Escreva um diálogo de oito falas entre duas personagens com nome, origem e ocupação."}, {"id": "course-ingles-26", "title": "Agenda semanal e hábitos", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Days of the week se escrevem com inicial maiúscula. On Monday localiza um dia, enquanto every Monday descreve repetição. Advérbios de frequência ajudam a apresentar hábitos. Compare o cronograma planejado com o realizado sem misturar o sujeito ou a concordância do verbo.", "phrase": "I study on Monday and Wednesday. My brother studies every day. We rest on Sunday.", "reading": "", "meaning": "Estudo na segunda e na quarta. Meu irmão estuda todos os dias. Descansamos no domingo.", "wrong": "My brother study every day.", "task": "Monte uma agenda de sete dias e explique sua frequência de estudo em seis frases."}, {"id": "course-ingles-27", "title": "Compras e escolhas no cotidiano", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Em compras, distinga preço de quantidade. How much can introduce preço e incontáveis; how many pergunta contáveis plurais. Um pedido com I'd like pode soar cortês. Confirme a escolha antes de encerrar a conversa e observe singular e plural.", "phrase": "I'd like two apples, please. How much are they? They are three dollars.", "reading": "", "meaning": "Quero duas maçãs, por favor. Quanto custam? Custam três dólares.", "wrong": "How many money are they?", "task": "Crie uma conversa de compra com três produtos, preços fictícios e confirmação do pedido."}, {"id": "course-ingles-28", "title": "Orientações e deslocamento", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Instruções podem usar a forma básica do verbo: turn left. Next to indica proximidade lateral; across from indica posição oposta. Leia um mapa simples e siga uma instrução por vez. Descreva pontos de referência sem usar seu endereço real.", "phrase": "Go straight and turn left. The library is next to the school. It is across from the park.", "reading": "", "meaning": "Siga em frente e vire à esquerda. A biblioteca fica ao lado da escola. Fica em frente ao parque, do outro lado.", "wrong": "Turn to lefted at the school.", "task": "Desenhe um mapa fictício e escreva dois trajetos de cinco instruções."}, {"id": "course-ingles-29", "title": "Diário de uma viagem", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "Uma narrativa ganha clareza com sequência temporal. Use passado simples para eventos concluídos e passado contínuo para contexto. First, then e finally ajudam a organizar a história. Não coloque o verbo no passado novamente depois de didn't.", "phrase": "We arrived on Friday. While I was waiting, I read a book. Then we went to the hotel.", "reading": "", "meaning": "Chegamos na sexta. Enquanto eu esperava, li um livro. Depois fomos ao hotel.", "wrong": "We didn't went to the hotel.", "task": "Narre uma viagem fictícia em 100 palavras e destaque cinco verbos no passado."}, {"id": "course-ingles-30", "title": "Entrevista e experiências", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "Apresente experiência com present perfect e esclareça um evento datado com passado simples. A pergunta de acompanhamento muda o foco de experiência para ocasião específica. Evite associar present perfect automaticamente a todo passado sem data: o sentido da relação com o presente continua relevante.", "phrase": "I have worked with different teams. Last year, I led a small project. I learned to listen carefully.", "reading": "", "meaning": "Trabalhei com equipes diferentes. No ano passado, liderei um pequeno projeto. Aprendi a ouvir com atenção.", "wrong": "Last year I have led a small project, como evento datado concluído.", "task": "Simule uma entrevista com seis perguntas e respostas sobre experiências fictícias."}, {"id": "course-ingles-31", "title": "Resolver um problema por e-mail", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "Em suporte, descreva o problema, quando começou e o resultado esperado. Use pedidos claros e corteses. Diferencie sintoma observado de hipótese sobre a causa. Um e-mail útil informa contexto sem expor senhas ou dados pessoais desnecessários.", "phrase": "The page doesn't open on my phone. The problem started yesterday. Could you help me check the settings?", "reading": "", "meaning": "A página não abre no meu celular. O problema começou ontem. Você poderia me ajudar a verificar as configurações?", "wrong": "Could you helped me check the settings?", "task": "Redija um e-mail de suporte com assunto, contexto, pedido e despedida."}, {"id": "course-ingles-32", "title": "Comparar propostas e tomar decisões", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "Compare alternativas com critérios, não apenas adjetivos vagos. Although introduz concessão e because apresenta causa. Explique qual fator pesa mais e distinga custo, prazo e qualidade. Confirme se o comparativo escolhido pertence ao adjetivo em uso.", "phrase": "The first option is cheaper, but the second is more reliable. Although it costs more, it saves time. We prefer the second option.", "reading": "", "meaning": "A primeira opção é mais barata, mas a segunda é mais confiável. Embora custe mais, economiza tempo. Preferimos a segunda opção.", "wrong": "The second option is more better in every way.", "task": "Compare dois planos fictícios em uma tabela e justifique a escolha em um parágrafo."}, {"id": "course-ingles-33", "title": "Relatório: resultado, evidência e limite", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Um relatório apresenta objetivo, método, resultado e interpretação. Use passiva quando o processo importar mais que o agente e modais de cautela quando a evidência for limitada. Não transforme associação em causa sem justificativa. Revise a referência dos pronomes e o período observado.", "phrase": "The data were collected over two weeks. The results suggest an improvement. However, a longer study is needed.", "reading": "", "meaning": "Os dados foram coletados durante duas semanas. Os resultados sugerem uma melhora. No entanto, é necessário um estudo mais longo.", "wrong": "The results proves that every future problem is solved.", "task": "Escreva um relatório fictício de 150 palavras com método, resultados e uma limitação."}, {"id": "course-ingles-34", "title": "Debate e contra-argumentação", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Reconhecer um argumento adversário não significa aceitá-lo integralmente. Introduza uma objeção, responda com razão verificável e delimite a conclusão. Whereas contrasta elementos; therefore liga premissa e consequência. Escolha conectivos pelo sentido e evite sequências contraditórias.", "phrase": "Some people prefer speed, whereas others value accuracy. Both matter. Therefore, the best solution depends on the task.", "reading": "", "meaning": "Algumas pessoas preferem velocidade, enquanto outras valorizam precisão. Ambas importam. Portanto, a melhor solução depende da tarefa.", "wrong": "Therefore significa oposição, sem relação de consequência.", "task": "Produza um debate escrito com posição, objeção, resposta e conclusão em 150 palavras."}, {"id": "course-ingles-35", "title": "Síntese de textos e atribuição de ideias", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Uma síntese integra ideias de textos sem apagar quem afirma o quê. Use verbos como argues, reports e suggests para atribuir posições. Parafrasear exige reconstruir a ideia, não trocar poucas palavras. Diferencie citações, inferências próprias e fatos relatados.", "phrase": "The first author argues that practice matters. The second highlights feedback. Together, the texts support a balanced approach.", "reading": "", "meaning": "O primeiro autor defende que a prática importa. O segundo destaca o feedback. Juntos, os textos sustentam uma abordagem equilibrada.", "wrong": "The second author highlight feedback.", "task": "Crie dois pequenos textos de posições diferentes e escreva uma síntese que atribua cada ideia."}, {"id": "course-ingles-36", "title": "Projeto final: proposta e defesa oral", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Uma proposta combina necessidade, solução, execução e critérios de sucesso. Antecipe riscos e prepare respostas a perguntas. Na defesa oral, organize notas em tópicos e explique decisões com exemplos. Revise clareza e registro antes de ampliar vocabulário ou complexidade sintática.", "phrase": "I propose a weekly study group. If we share feedback, we can improve our work. The results will be reviewed every month.", "reading": "", "meaning": "Proponho um grupo de estudo semanal. Se compartilharmos feedback, poderemos melhorar nosso trabalho. Os resultados serão revistos todo mês.", "wrong": "If we will share feedback, we can improve our work.", "task": "Prepare uma proposta de 200 palavras e uma apresentação oral de três minutos; depois registre uma autoavaliação."}], "espanhol": [{"id": "course-espanhol-25", "title": "Apresentação e conversa cotidiana", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Para manter uma conversa, responda à informação recebida e faça uma pergunta relacionada. Me llamo informa nome; soy apresenta origem ou identidade. Pratique formas de tratamento consistentes e observe diferenças regionais sem supor que uma única variedade representa todos os falantes.", "phrase": "Hola, soy Ana. Vivo en Brasil y estudio español. ¿Y tú?", "reading": "", "meaning": "Olá, sou Ana. Moro no Brasil e estudo espanhol. E você?", "wrong": "Yo vive en Brasil.", "task": "Crie um diálogo de oito falas com apresentação, origem e estudo."}, {"id": "course-espanhol-26", "title": "Agenda e frequência", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Os dias da semana normalmente se escrevem com minúscula em espanhol. El lunes pode localizar uma segunda; los lunes apresenta hábito. Para rotinas, mantenha presente e concordância. Observe que o artigo pode participar da expressão temporal sem preposição adicional.", "phrase": "Estudio los lunes y los miércoles. Mi hermano trabaja por la mañana. Descansamos el domingo.", "reading": "", "meaning": "Estudo às segundas e quartas. Meu irmão trabalha de manhã. Descansamos no domingo.", "wrong": "Nosotros descansa el domingo.", "task": "Monte uma agenda semanal fictícia e descreva seis hábitos."}, {"id": "course-espanhol-27", "title": "Compras, números e preços", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Em uma compra, formule pedido, quantidade e confirmação. Cuánto varia com o nome em perguntas como cuántas manzanas. Precio e cantidad não são a mesma informação. Use por favor e gracias conforme o contexto e confira o produto antes de encerrar o diálogo.", "phrase": "Quisiera dos manzanas. ¿Cuánto cuestan? Cuestan tres euros.", "reading": "", "meaning": "Quero duas maçãs. Quanto custam? Custam três euros.", "wrong": "Las manzanas cuesta tres euros.", "task": "Escreva uma compra fictícia com três produtos e um pedido de confirmação."}, {"id": "course-espanhol-28", "title": "Direções e transporte", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Para dar orientações, organize as instruções pela ordem do trajeto. A la derecha e a la izquierda indicam direção; al lado de indica posição relativa. Não traduza toda ocorrência de em por en sem verificar a construção. Utilize lugares fictícios.", "phrase": "Sigue recto y gira a la izquierda. La biblioteca está al lado de la escuela. El parque está enfrente.", "reading": "", "meaning": "Siga em frente e vire à esquerda. A biblioteca fica ao lado da escola. O parque fica em frente.", "wrong": "La biblioteca es al lado de la escuela.", "task": "Desenhe um mapa e escreva dois trajetos de cinco instruções."}, {"id": "course-espanhol-29", "title": "Diário de viagem e passado", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "Uma narrativa distingue cenário e evento. Use imperfecto para o contexto e indefinido para acontecimentos delimitados. Primero, después e al final ordenam a sequência. Evite misturar tempos sem uma mudança intencional do ponto de vista.", "phrase": "Llegamos el viernes. Mientras esperaba, leía un libro. Después fuimos al hotel.", "reading": "", "meaning": "Chegamos na sexta. Enquanto eu esperava, lia um livro. Depois fomos ao hotel.", "wrong": "Ayer nosotros llegamos y después iremos, para uma sequência toda concluída.", "task": "Narre uma viagem fictícia em 100 palavras e explique duas escolhas de tempo verbal."}, {"id": "course-espanhol-30", "title": "Entrevista e experiência profissional", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "Em uma entrevista, forneça exemplo que sustente a habilidade declarada. O composto com haber apresenta experiência em certos contextos e variedades; o indefinido situa eventos delimitados. Não use a existência de uma data como única regra para todas as variedades de espanhol.", "phrase": "He trabajado con varios equipos. El año pasado coordiné un proyecto. Aprendí a escuchar mejor.", "reading": "", "meaning": "Trabalhei com várias equipes. No ano passado coordenei um projeto. Aprendi a ouvir melhor.", "wrong": "Yo has trabajado con varios equipos.", "task": "Crie seis perguntas e respostas sobre experiências fictícias, com um exemplo concreto por habilidade."}, {"id": "course-espanhol-31", "title": "Pedido de ajuda por e-mail", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "Apresente sintoma, início do problema e solicitação. Um pedido com podría pode suavizar a interação. Trate hipóteses como hipóteses e não como fatos comprovados. Revise o tratamento escolhido e evite incluir dados privados em mensagens de exemplo.", "phrase": "La página no se abre en mi teléfono. El problema empezó ayer. ¿Podría ayudarme a revisar la configuración?", "reading": "", "meaning": "A página não abre no meu telefone. O problema começou ontem. Poderia me ajudar a revisar a configuração?", "wrong": "¿Podría ayudar yo a revisar la configuración?, querendo pedir ajuda para si.", "task": "Redija um e-mail de suporte com assunto, contexto, pedido e despedida."}, {"id": "course-espanhol-32", "title": "Comparar alternativas", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "Compare alternativas com critérios como custo, prazo e confiança. Más que estabelece uma comparação e mejor não precisa de más. Aunque permite apresentar uma concessão; porque explica uma causa. Verifique se a conclusão decorre dos critérios apresentados.", "phrase": "La primera opción es más barata, pero la segunda es más fiable. Aunque cuesta más, ahorra tiempo. Preferimos la segunda.", "reading": "", "meaning": "A primeira opção é mais barata, mas a segunda é mais confiável. Embora custe mais, economiza tempo. Preferimos a segunda.", "wrong": "La segunda opción es más mejor.", "task": "Compare dois planos fictícios numa tabela e justifique uma escolha em um parágrafo."}, {"id": "course-espanhol-33", "title": "Relatório e cautela na conclusão", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Um relatório separa dados e interpretação. Sugiere que introduz uma leitura menos categórica que demuestra que. Use conectivos para evidenciar limites e não afirme causalidade apenas porque duas mudanças ocorreram juntas. Identifique também o período e o método observados.", "phrase": "Se recogieron datos durante dos semanas. Los resultados sugieren una mejora. Sin embargo, hace falta un estudio más largo.", "reading": "", "meaning": "Foram coletados dados por duas semanas. Os resultados sugerem melhora. No entanto, falta um estudo mais longo.", "wrong": "Los resultados sugiere una mejora.", "task": "Escreva um relatório fictício de 150 palavras com método, resultado e limitação."}, {"id": "course-espanhol-34", "title": "Debate e contra-argumento", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Uma resposta argumentativa identifica a objeção antes de refutá-la. Mientras que pode contrapor posições e por lo tanto apresenta consequência. A força da conclusão deve ser proporcional à evidência. Evite tratar qualquer opinião diferente como erro gramatical ou factual.", "phrase": "Algunos valoran la rapidez, mientras que otros prefieren la precisión. Ambas son importantes. Por lo tanto, la elección depende de la tarea.", "reading": "", "meaning": "Alguns valorizam rapidez, enquanto outros preferem precisão. Ambas são importantes. Portanto, a escolha depende da tarefa.", "wrong": "Por lo tanto significa uma ressalva, sem consequência.", "task": "Produza uma defesa com posição, objeção, resposta e conclusão em 150 palavras."}, {"id": "course-espanhol-35", "title": "Síntese e atribuição de fontes", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Uma síntese relaciona contribuições de textos e preserva a atribuição de ideias. Afirma, sostiene e señala indicam maneiras diferentes de apresentar uma posição. Parafraseie sem copiar a organização inteira e deixe claro quando acrescentar uma inferência própria.", "phrase": "El primer autor destaca la práctica. El segundo insiste en la revisión. Los dos proponen un aprendizaje activo.", "reading": "", "meaning": "O primeiro autor destaca a prática. O segundo insiste na revisão. Ambos propõem aprendizagem ativa.", "wrong": "Los dos propone un aprendizaje activo.", "task": "Escreva dois parágrafos de posições diferentes e uma síntese que indique a origem de cada ideia."}, {"id": "course-espanhol-36", "title": "Projeto final: proposta e apresentação", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Planeje objetivo, solução, etapas e avaliação. Ao defender uma proposta, antecipe perguntas e reconheça limitações sem abandonar a tese. Revise tratamento, subjuntivo e conectivos e prepare uma versão oral apoiada em tópicos, não numa leitura acelerada.", "phrase": "Propongo un grupo semanal de estudio. Si compartimos comentarios, mejoraremos. Revisaremos los resultados cada mes.", "reading": "", "meaning": "Proponho um grupo semanal de estudo. Se compartilharmos comentários, melhoraremos. Revisaremos os resultados todo mês.", "wrong": "Si compartiríamos comentarios, mejoraremos.", "task": "Prepare uma proposta de 200 palavras e uma apresentação oral de três minutos com autoavaliação."}], "italiano": [{"id": "course-italiano-25", "title": "Apresentação em uma conversa completa", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Uma conversa de apresentação combina saudação, nome, origem e interesse. Sono apresenta identidade e mi chiamo informa o nome. Escolha tu ou Lei conforme o contexto e mantenha esse tratamento. Ouça a fala como sequência de unidades, prestando atenção às consoantes duplas.", "phrase": "Ciao, mi chiamo Anna. Sono brasiliana e studio italiano. E tu?", "reading": "", "meaning": "Olá, meu nome é Anna. Sou brasileira e estudo italiano. E você?", "wrong": "Io è brasiliana.", "task": "Crie um diálogo de oito falas com apresentação e perguntas de acompanhamento."}, {"id": "course-italiano-26", "title": "Agenda e hábitos semanais", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Dias da semana se escrevem normalmente com minúscula. Lunedì pode localizar um dia e il lunedì pode indicar hábito, conforme o contexto. Para rotina, mantenha presente e concordância. Inclua marcadores de frequência para evitar uma lista de ações sem relação temporal.", "phrase": "Studio il lunedì e il mercoledì. Mio fratello lavora la mattina. Riposiamo la domenica.", "reading": "", "meaning": "Estudo às segundas e quartas. Meu irmão trabalha de manhã. Descansamos aos domingos.", "wrong": "Noi riposa la domenica.", "task": "Monte uma agenda fictícia de sete dias e descreva seis hábitos."}, {"id": "course-italiano-27", "title": "Compras e quantidades", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Vorrei torna um pedido mais cortês. Quanto costa pergunta por um item; quanto costano pode perguntar por vários. Número, gênero e plural precisam permanecer coerentes ao retomar os produtos. Faça a confirmação do pedido antes de encerrar a conversa.", "phrase": "Vorrei due mele. Quanto costano? Costano tre euro.", "reading": "", "meaning": "Quero duas maçãs. Quanto custam? Custam três euros.", "wrong": "Le mele costa tre euro.", "task": "Escreva uma compra fictícia com três produtos e perguntas sobre preço e quantidade."}, {"id": "course-italiano-28", "title": "Direções e deslocamento", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Para orientar alguém, organize os pontos na ordem do trajeto. A destra e a sinistra indicam direção; accanto a indica proximidade. Observe as preposições e suas contrações com artigos. Um desenho simples ajuda a conferir se a descrição leva ao destino.", "phrase": "Vai dritto e gira a sinistra. La biblioteca è accanto alla scuola. Il parco è di fronte.", "reading": "", "meaning": "Siga em frente e vire à esquerda. A biblioteca fica ao lado da escola. O parque fica em frente.", "wrong": "La biblioteca è accanto a la scuola.", "task": "Desenhe um mapa fictício e escreva dois trajetos com cinco instruções cada."}, {"id": "course-italiano-29", "title": "Narrativa de viagem", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "Combine imperfetto para cenário com passato prossimo para eventos que avançam a narrativa. O auxiliar precisa corresponder ao verbo e o particípio com essere concorda com o sujeito. Una volta, poi e infine podem organizar uma história de forma clara.", "phrase": "Siamo arrivati venerdì. Mentre aspettavo, leggevo un libro. Poi siamo andati in albergo.", "reading": "", "meaning": "Chegamos na sexta. Enquanto eu esperava, lia um livro. Depois fomos ao hotel.", "wrong": "Noi siamo arrivato venerdì.", "task": "Conte uma viagem fictícia em 100 palavras e explique as escolhas de auxiliar."}, {"id": "course-italiano-30", "title": "Entrevista e experiências", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "Uma entrevista ganha força quando habilidades são apoiadas em experiências concretas. Use formas passadas coerentes e exemplos com tempo ou contexto. Prefira frases que você consegue explicar a vocabulário complexo sem controle de concordância ou significado.", "phrase": "Ho lavorato con diversi gruppi. L'anno scorso ho coordinato un progetto. Ho imparato ad ascoltare meglio.", "reading": "", "meaning": "Trabalhei com vários grupos. No ano passado coordenei um projeto. Aprendi a ouvir melhor.", "wrong": "Io ha lavorato con diversi gruppi.", "task": "Crie seis perguntas e respostas sobre uma trajetória profissional fictícia."}, {"id": "course-italiano-31", "title": "E-mail de suporte", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "Especifique o que acontece, quando começou e qual ajuda espera. Potrebbe permite pedir ajuda de forma cortês. Não inclua senhas e não trate uma hipótese técnica como causa comprovada. Revise o tratamento formal e as formas pronominais utilizadas.", "phrase": "La pagina non si apre sul mio telefono. Il problema è iniziato ieri. Potrebbe aiutarmi a controllare le impostazioni?", "reading": "", "meaning": "A página não abre no meu telefone. O problema começou ontem. Poderia me ajudar a verificar as configurações?", "wrong": "Potrebbe aiutare io a controllare le impostazioni?", "task": "Redija um e-mail de suporte fictício com assunto, contexto e pedido."}, {"id": "course-italiano-32", "title": "Comparação e justificativa de escolha", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "Compare opções a partir de critérios explícitos. Più e meno estabelecem comparações, mas migliore é uma forma própria que não precisa receber più. Sebbene e anche se têm construções próprias; não troque o modo verbal mecanicamente. Explique qual fator teve mais peso.", "phrase": "La prima opzione costa meno, ma la seconda è più affidabile. Fa risparmiare tempo. Preferiamo la seconda.", "reading": "", "meaning": "A primeira opção custa menos, mas a segunda é mais confiável. Economiza tempo. Preferimos a segunda.", "wrong": "La seconda opzione è più migliore.", "task": "Compare dois planos fictícios e escreva uma justificativa com um benefício e uma ressalva."}, {"id": "course-italiano-33", "title": "Relatório de resultados", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Um relatório separa procedimento, observação e conclusão. A passiva pode focalizar os dados e verbos como suggerire indicam cautela. Diga o período e o alcance da análise e evite transformar um resultado limitado em uma conclusão universal.", "phrase": "I dati sono stati raccolti per due settimane. I risultati suggeriscono un miglioramento. Tuttavia, serve uno studio più lungo.", "reading": "", "meaning": "Os dados foram coletados por duas semanas. Os resultados sugerem uma melhora. No entanto, é necessário um estudo mais longo.", "wrong": "I risultati suggerisce un miglioramento.", "task": "Escreva um relatório fictício de 150 palavras com uma limitação explícita."}, {"id": "course-italiano-34", "title": "Debate e contraposição", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Uma argumentação eficaz apresenta uma objeção de modo fiel antes de respondê-la. Mentre pode contrapor perspectivas; pertanto introduz uma consequência. Não conclua mais do que as razões permitem e revise a relação entre tese, exemplo e conclusão.", "phrase": "Alcuni preferiscono la rapidità, mentre altri danno valore alla precisione. Entrambe contano. Pertanto, la scelta dipende dal compito.", "reading": "", "meaning": "Alguns preferem rapidez, enquanto outros valorizam precisão. Ambas importam. Portanto, a escolha depende da tarefa.", "wrong": "Pertanto significa oposição, sem relação de consequência.", "task": "Produza uma defesa de 150 palavras com objeção e resposta fundamentada."}, {"id": "course-italiano-35", "title": "Síntese e fontes", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Relacione textos sem apagar a origem das posições. Sostiene, descrive e propone ajudam a atribuir ideias. Parafrasear não é apenas trocar sinônimos e manter toda a frase original. Sinalize quando uma conclusão é sua e quando foi apresentada por uma fonte.", "phrase": "Il primo autore sottolinea la pratica. Il secondo insiste sulla revisione. Entrambi propongono un apprendimento attivo.", "reading": "", "meaning": "O primeiro autor destaca a prática. O segundo insiste na revisão. Ambos propõem aprendizagem ativa.", "wrong": "Entrambi propone un apprendimento attivo.", "task": "Escreva dois textos curtos de perspectivas diferentes e uma síntese comparativa."}, {"id": "course-italiano-36", "title": "Projeto final: proposta e defesa", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Organize uma proposta por necessidade, solução, execução e verificação. Antecipe riscos e formule critérios de sucesso. Na fala, use notas curtas e exemplos. Revise congiuntivo, condizionale, auxiliares e concordância antes de apresentar a versão final.", "phrase": "Propongo un gruppo di studio settimanale. Se condividiamo i commenti, possiamo migliorare. Valuteremo i risultati ogni mese.", "reading": "", "meaning": "Proponho um grupo semanal de estudo. Se compartilharmos comentários, poderemos melhorar. Avaliaremos os resultados todo mês.", "wrong": "Se condivideremmo i commenti, possiamo migliorare.", "task": "Prepare uma proposta de 200 palavras e uma apresentação oral de três minutos com autoavaliação."}], "japones": [{"id": "course-japones-25", "title": "Diálogo completo de apresentação", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Uma apresentação inclui cumprimento, nome e uma informação adequada ao contexto. O sujeito pode ser omitido quando recuperável. Use o estilo polido de modo consistente e observe は como marcador de tópico. A romanização ajuda no início, mas pratique reconhecer as palavras em kana e kanji estudados.", "phrase": "はじめまして。アナです。ブラジルから来ました。よろしくお願いします。", "reading": "Hajimemashite. Ana desu. Burajiru kara kimashita. Yoroshiku onegaishimasu.", "meaning": "Prazer em conhecê-lo. Sou Ana. Vim do Brasil. Conto com sua boa disposição.", "wrong": "ブラジルから来ました significa vou ao Brasil amanhã.", "task": "Crie um diálogo curto de apresentação; identifique cumprimento, nome e origem, usando leitura de apoio se necessário."}, {"id": "course-japones-26", "title": "Agenda semanal e tempo", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Horários e dias ajudam a organizar uma rotina. 月曜日 é segunda-feira e 水曜日 é quarta-feira. 毎週 indica toda semana; に pode marcar um momento específico, mas não acompanha toda expressão de tempo. Pratique a localização temporal antes de tentar frases muito longas.", "phrase": "毎週、月曜日と水曜日に勉強します。日曜日は休みます。", "reading": "Maishū, getsuyōbi to suiyōbi ni benkyō shimasu. Nichiyōbi wa yasumimasu.", "meaning": "Estudo toda semana às segundas e quartas. Descanso no domingo.", "wrong": "日曜日は休みます significa trabalho sem descansar no domingo.", "task": "Monte uma agenda fictícia de sete dias e escreva quatro frases curtas sobre ela."}, {"id": "course-japones-27", "title": "Compras e contagem", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Classificadores acompanham a contagem e dependem do que está sendo contado. 一つ e 二つ são formas úteis de uma série geral, sem resolver todos os casos. Ao comprar, identifique item, quantidade e preço. ください participa de pedidos e いくら pergunta preço.", "phrase": "りんごを二つください。いくらですか。ありがとうございます。", "reading": "Ringo o futatsu kudasai. Ikura desu ka. Arigatō gozaimasu.", "meaning": "Duas maçãs, por favor. Quanto custa? Obrigado.", "wrong": "りんごを二つください significa quero vinte maçãs.", "task": "Escreva um diálogo de compra, marcando item, quantidade e confirmação de preço."}, {"id": "course-japones-28", "title": "Orientação por um mapa", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Direções exigem relacionar ações e pontos de referência. 右 e 左 indicam direita e esquerda. まっすぐ indica seguir reto. に pode marcar a direção em uma construção de virar; a escolha de partículas depende do verbo. Confirme no desenho se a sequência chega ao destino.", "phrase": "まっすぐ行って、左に曲がってください。図書館は学校の隣です。", "reading": "Massugu itte, hidari ni magatte kudasai. Toshokan wa gakkō no tonari desu.", "meaning": "Siga reto e vire à esquerda, por favor. A biblioteca fica ao lado da escola.", "wrong": "図書館は学校の隣です significa a biblioteca está muito longe da escola, sem referência de proximidade.", "task": "Desenhe um bairro fictício e escreva orientações curtas para dois lugares."}, {"id": "course-japones-29", "title": "Diário de viagem", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "Uma narrativa ordena eventos e fornece contexto. No registro polido, use formas como 行きました e 読みました. Quando apresentar uma ação em curso, observe ていました. Conectivos temporais ajudam a relacionar as ações sem depender de repetir uma lista de sujeitos.", "phrase": "金曜日に東京に着きました。駅で待っている間、本を読みました。その後、ホテルに行きました。", "reading": "Kinyōbi ni Tōkyō ni tsukimashita. Eki de matte iru aida, hon o yomimashita. Sono ato, hoteru ni ikimashita.", "meaning": "Cheguei a Tóquio na sexta. Enquanto esperava na estação, li um livro. Depois fui ao hotel.", "wrong": "ホテルに行きました significa não fui ao hotel.", "task": "Relate uma viagem fictícia em cinco frases e marque a ordem dos eventos."}, {"id": "course-japones-30", "title": "Experiência e entrevista", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "Relate experiência e depois acrescente um exemplo concreto. たことがあります apresenta experiência, enquanto uma data permite situar um evento específico. Em entrevista, mantenha o registro apropriado e não confunda uma experiência já vivida com um simples desejo de realizá-la.", "phrase": "日本で働いたことがあります。去年、小さなチームで仕事をしました。たくさん学びました。", "reading": "Nihon de hataraita koto ga arimasu. Kyonen, chiisana chīmu de shigoto o shimashita. Takusan manabimashita.", "meaning": "Já trabalhei no Japão. No ano passado, trabalhei em uma pequena equipe. Aprendi muito.", "wrong": "日本で働いたことがあります significa apenas quero trabalhar no Japão, sem experiência.", "task": "Crie quatro perguntas e respostas sobre experiências fictícias e uma habilidade aprendida."}, {"id": "course-japones-31", "title": "Pedido de ajuda por mensagem", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "Uma mensagem de suporte precisa de sintoma e pedido claro. てもらえますか solicita uma ação em benefício do falante em muitos contextos. O grau de cortesia depende também de interlocutor e situação. Não inclua senhas reais nem afirme uma causa que você ainda não verificou.", "phrase": "ページが開きません。昨日からこの問題があります。確認してもらえますか。", "reading": "Pēji ga hirakimasen. Kinō kara kono mondai ga arimasu. Kakunin shite moraemasu ka.", "meaning": "A página não abre. Esse problema existe desde ontem. Poderia verificar para mim?", "wrong": "ページが開きません significa a página abre normalmente.", "task": "Escreva uma solicitação de ajuda com sintoma, início do problema e pedido cortês."}, {"id": "course-japones-32", "title": "Comparar alternativas", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "Uma escolha pode ser justificada por preço, prazo e confiabilidade. より fornece referência de comparação; ほう destaca um lado. しかし ou が pode introduzir contraste. Verifique a que cada expressão se refere e não confunda mais barato com melhor em qualquer contexto.", "phrase": "一つ目の案は安いです。しかし、二つ目の案のほうが便利です。私は二つ目を選びます。", "reading": "Hitotsume no an wa yasui desu. Shikashi, futatsume no an no hō ga benri desu. Watashi wa futatsume o erabimasu.", "meaning": "A primeira proposta é barata. Porém, a segunda é mais conveniente. Escolho a segunda.", "wrong": "二つ目の案のほうが便利です significa a primeira é mais conveniente, nessa comparação.", "task": "Compare duas propostas fictícias numa tabela e escreva uma justificativa curta."}, {"id": "course-japones-33", "title": "Relatório e interpretação prudente", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Um relatório distingue coleta, observação e interpretação. Construções como と考えられます podem suavizar uma conclusão quando apropriado. Delimite período e evidência. A forma polida ou simples precisa permanecer consistente, e a passiva deve ser escolhida por sua função, não apenas por parecer formal.", "phrase": "二週間、データを集めました。結果には改善が見られました。ただし、さらに調査が必要です。", "reading": "Nishūkan, dēta o atsumemashita. Kekka ni wa kaizen ga miraremashita. Tadashi, sara ni chōsa ga hitsuyō desu.", "meaning": "Coletei dados durante duas semanas. Foi observada melhora nos resultados. Contudo, são necessárias mais investigações.", "wrong": "さらに調査が必要です significa que nenhuma investigação adicional é necessária.", "task": "Redija um relatório de seis a oito frases com procedimento, resultado e limite."}, {"id": "course-japones-34", "title": "Debate e contra-argumentação", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Apresente fielmente uma objeção antes de responder. 一方で pode contrastar perspectivas e したがって introduz consequência. Diferencie um fato assumido de uma hipótese. A conclusão precisa decorrer das razões e não de uma simples sequência de conectivos formais.", "phrase": "速さを重視する人もいれば、正確さを重視する人もいます。どちらも大切です。したがって、目的に応じて選ぶ必要があります。", "reading": "Hayasa o jūshi suru hito mo ireba, seikakusa o jūshi suru hito mo imasu. Dochira mo taisetsu desu. Shitagatte, mokuteki ni ōjite erabu hitsuyō ga arimasu.", "meaning": "Há quem priorize rapidez e quem priorize precisão. Ambas são importantes. Portanto, é necessário escolher conforme o objetivo.", "wrong": "どちらも大切です significa que nenhum dos dois é importante.", "task": "Defenda uma posição em seis frases, reconheça uma objeção e responda a ela."}, {"id": "course-japones-35", "title": "Síntese de posições e fontes", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Ao sintetizar, separe o que cada autor defende da sua própria interpretação. Expressões como によると podem indicar fonte, com construções complementares adequadas. Preserve o sentido sem copiar toda a organização. Identifique o predicado e as orações modificadoras antes de resumir.", "phrase": "一人目の著者は練習を重視しています。二人目は復習の重要性を述べています。どちらも積極的な学習を勧めています。", "reading": "Hitorime no chosha wa renshū o jūshi shite imasu. Futarime wa fukushū no jūyōsei o nobete imasu. Dochira mo sekkyokuteki na gakushū o susumete imasu.", "meaning": "O primeiro autor valoriza a prática. O segundo fala da importância da revisão. Ambos recomendam aprendizagem ativa.", "wrong": "どちらも積極的な学習を勧めています significa ambos desaconselham a aprendizagem ativa.", "task": "Crie dois pontos de vista curtos e uma síntese que atribua cada ideia à sua fonte."}, {"id": "course-japones-36", "title": "Projeto final: proposta e apresentação", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Defina objetivo, solução, etapas e critérios de avaliação. Prepare uma versão escrita e outra oral em tópicos. Revise partículas, registro, sequência temporal e retomadas de informação. Registre dúvidas para consultar, em vez de inserir estruturas que você não consegue explicar.", "phrase": "毎週、勉強会を開くことを提案します。意見を共有すれば、お互いに学べます。毎月、結果を確認します。", "reading": "Maishū, benkyōkai o hiraku koto o teian shimasu. Iken o kyōyū sureba, otagai ni manabemasu. Maitsuki, kekka o kakunin shimasu.", "meaning": "Proponho realizar um grupo de estudo semanal. Se compartilharmos opiniões, poderemos aprender uns com os outros. Conferiremos os resultados todo mês.", "wrong": "毎月、結果を確認します significa nunca verificaremos os resultados.", "task": "Prepare uma proposta de oito a doze frases e uma fala de dois minutos; registre uma autoavaliação."}], "chines": [{"id": "course-chines-25", "title": "Conversa completa de apresentação", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Combine saudação, nome e uma informação pessoal fictícia. Os verbos não recebem conjugação por pessoa. Use 是 em identificação nominal e não o insira automaticamente antes de qualquer predicado. Compare pinyin e caracteres para reduzir gradualmente a dependência da escrita latina.", "phrase": "你好，我叫安娜。我是巴西人。我学习中文。你呢？", "reading": "Nǐ hǎo, wǒ jiào Ānnà. Wǒ shì Bāxī rén. Wǒ xuéxí Zhōngwén. Nǐ ne?", "meaning": "Olá, meu nome é Anna. Sou brasileira. Estudo chinês. E você?", "wrong": "我是巴西人 significa sou japonesa.", "task": "Crie um diálogo de apresentação com nome, origem, estudo e uma pergunta de acompanhamento."}, {"id": "course-chines-26", "title": "Agenda e frequência", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Expressões de tempo ajudam a interpretar a ação e costumam anteceder o verbo. 每周 significa toda semana e 星期一 é segunda-feira. Não acrescente terminações verbais portuguesas ou um marcador de passado em toda frase de rotina. Pratique primeiro uma agenda curta e verificável.", "phrase": "我每周一和周三学习中文。星期天我休息。哥哥每天工作。", "reading": "Wǒ měi zhōuyī hé zhōusān xuéxí Zhōngwén. Xīngqītiān wǒ xiūxi. Gēge měitiān gōngzuò.", "meaning": "Estudo chinês às segundas e quartas. No domingo descanso. Meu irmão mais velho trabalha todos os dias.", "wrong": "星期天我休息 significa trabalho sem descanso no domingo.", "task": "Monte uma agenda de sete dias e descreva quatro hábitos de uma pessoa fictícia."}, {"id": "course-chines-27", "title": "Compras e classificadores", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Número e classificador ajudam a indicar quantidade. 个 é usado com muitos itens, mas não com todos. 两 costuma anteceder classificadores para a quantidade dois. 多少钱 pergunta preço e 请 pode ajudar em pedidos corteses. Confirme produto e quantidade antes de encerrar.", "phrase": "我想买两个苹果。一共多少钱？谢谢。", "reading": "Wǒ xiǎng mǎi liǎng ge píngguǒ. Yígòng duōshao qián? Xièxie.", "meaning": "Quero comprar duas maçãs. Quanto custa ao todo? Obrigado.", "wrong": "我想买两个苹果 significa quero comprar vinte maçãs.", "task": "Escreva uma conversa de compra com quantidade, preço fictício e agradecimento."}, {"id": "course-chines-28", "title": "Direções e posições", "stage": 0, "module": "1 · Básico", "language": true, "extension": true, "theory": "Indique ações e pontos de referência pela ordem do trajeto. 左边 e 右边 expressam lados e 旁边 indica proximidade. Em descrições de localização, observe 在 e a relação entre o lugar e o objeto. Um mapa fictício permite conferir o sentido sem publicar endereços reais.", "phrase": "一直走，然后向左转。图书馆在学校旁边。公园在对面。", "reading": "Yìzhí zǒu, ránhòu xiàng zuǒ zhuǎn. Túshūguǎn zài xuéxiào pángbiān. Gōngyuán zài duìmiàn.", "meaning": "Siga reto e depois vire à esquerda. A biblioteca fica ao lado da escola. O parque fica do outro lado, em frente.", "wrong": "图书馆在学校旁边 significa que a biblioteca não fica perto da escola.", "task": "Desenhe um mapa e escreva duas orientações curtas com pontos de referência."}, {"id": "course-chines-29", "title": "Diário de viagem e sequência", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "Narre os eventos com marcadores temporais e ordem coerente. Verbos não mudam por pessoa ou tempo; aspecto, vocabulário e contexto cumprem funções importantes. Não trate 了 como equivalente automático de qualquer passado. Primeiro delimite o evento que deseja apresentar.", "phrase": "我星期五到了北京。等车的时候，我看了一本书。后来我去了酒店。", "reading": "Wǒ xīngqīwǔ dào le Běijīng. Děng chē de shíhou, wǒ kàn le yì běn shū. Hòulái wǒ qù le jiǔdiàn.", "meaning": "Cheguei a Pequim na sexta. Enquanto esperava o transporte, li um livro. Depois fui ao hotel.", "wrong": "后来我去了酒店 significa não fui ao hotel.", "task": "Conte uma viagem fictícia em cinco frases e explique a função de um marcador temporal."}, {"id": "course-chines-30", "title": "Entrevista e experiência", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "过 pode apresentar experiência, enquanto um evento datado precisa de seu próprio contexto. Uma entrevista pede exemplos que sustentem a habilidade afirmada. Distinguir o que aconteceu do que se pretende fazer ajuda a escolher as construções sem transferir automaticamente os tempos portugueses.", "phrase": "我在不同的团队工作过。去年，我负责了一个小项目。我学会了认真听取意见。", "reading": "Wǒ zài bùtóng de tuánduì gōngzuò guo. Qùnián, wǒ fùzé le yí ge xiǎo xiàngmù. Wǒ xuéhuì le rènzhēn tīngqǔ yìjiàn.", "meaning": "Já trabalhei em equipes diferentes. No ano passado fui responsável por um pequeno projeto. Aprendi a ouvir opiniões com atenção.", "wrong": "我在不同的团队工作过 significa que nunca trabalhei em equipe.", "task": "Crie quatro perguntas e respostas sobre uma trajetória profissional fictícia."}, {"id": "course-chines-31", "title": "Pedido de ajuda por mensagem", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "Uma mensagem útil descreve sintoma, início e pedido. 从昨天开始 indica início temporal e 可以 participar de uma solicitação de ajuda. Não afirme uma causa sem evidência e não exponha senhas ou dados pessoais. Revise ordem das expressões de tempo e dos complementos.", "phrase": "我的手机打不开这个网页。从昨天开始就这样了。可以帮我检查一下吗？", "reading": "Wǒ de shǒujī dǎbukāi zhège wǎngyè. Cóng zuótiān kāishǐ jiù zhèyàng le. Kěyǐ bāng wǒ jiǎnchá yíxià ma?", "meaning": "Meu telefone não consegue abrir esta página. Está assim desde ontem. Pode me ajudar a verificar?", "wrong": "可以帮我检查一下吗 significa que toda ajuda está proibida.", "task": "Escreva uma solicitação fictícia de suporte com sintoma, início e pedido."}, {"id": "course-chines-32", "title": "Comparar propostas", "stage": 1, "module": "2 · Intermediário", "language": true, "extension": true, "theory": "比 apresenta uma referência de comparação e 更 pode destacar aumento de um grau. A comparação precisa indicar quais alternativas estão envolvidas. 但是 contrapõe fatores; 因此 aponta consequência. Uma opção mais barata não é automaticamente a mais adequada em todo cenário.", "phrase": "第一个方案更便宜，但是第二个更可靠。它能节省时间。因此，我选择第二个。", "reading": "Dì yī ge fāng'àn gèng piányi, dànshì dì èr ge gèng kěkào. Tā néng jiéshěng shíjiān. Yīncǐ, wǒ xuǎnzé dì èr ge.", "meaning": "A primeira proposta é mais barata, mas a segunda é mais confiável. Ela economiza tempo. Portanto, escolho a segunda.", "wrong": "我选择第二个 significa escolho a primeira proposta.", "task": "Compare dois planos fictícios e justifique a escolha com um benefício e uma limitação."}, {"id": "course-chines-33", "title": "Relatório e conclusão prudente", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Separe coleta de dados, observação e interpretação. 表明 pode introduzir o que um resultado indica e 可能 pode limitar a certeza. Explique período e critério usados e não extrapole uma observação curta para uma regra universal. O texto deve deixar clara a relação entre frases.", "phrase": "我们收集了两周的数据。结果表明情况有所改善。不过，还需要进一步研究。", "reading": "Wǒmen shōují le liǎng zhōu de shùjù. Jiéguǒ biǎomíng qíngkuàng yǒusuǒ gǎishàn. Búguò, hái xūyào jìnyíbù yánjiū.", "meaning": "Coletamos dados por duas semanas. Os resultados indicam alguma melhora. Contudo, ainda é preciso pesquisar mais.", "wrong": "还需要进一步研究 significa que nenhuma pesquisa adicional é necessária.", "task": "Redija um relatório fictício de seis a oito frases com método, resultado e limite."}, {"id": "course-chines-34", "title": "Debate e objeções", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Uma argumentação precisa representar corretamente a posição contrária antes de responder. 而 pode contrastar elementos e 因此 introduz consequência. Indique o alcance da conclusão e a evidência necessária. Usar muitos conectivos não substitui uma sequência de razões compreensível.", "phrase": "有些人重视速度，而另一些人更看重准确性。两者都很重要。因此，选择取决于任务。", "reading": "Yǒuxiē rén zhòngshì sùdù, ér lìng yìxiē rén gèng kànzhòng zhǔnquèxìng. Liǎng zhě dōu hěn zhòngyào. Yīncǐ, xuǎnzé qǔjué yú rènwu.", "meaning": "Algumas pessoas valorizam velocidade, enquanto outras valorizam mais precisão. Ambas importam. Portanto, a escolha depende da tarefa.", "wrong": "两者都很重要 significa nenhum dos dois importa.", "task": "Defenda uma posição em seis frases e acrescente uma objeção e uma resposta."}, {"id": "course-chines-35", "title": "Síntese de textos e atribuição", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Diga quem apresenta cada argumento e diferencie relato de interpretação própria. 强调 destaca uma ideia e 指出 pode apresentar uma observação atribuída a alguém. Ao resumir, preserve a posição de cada texto e não acrescente certeza que a fonte não oferece.", "phrase": "第一位作者强调练习。第二位作者指出复习的重要性。两位作者都支持主动学习。", "reading": "Dì yī wèi zuòzhě qiángdiào liànxí. Dì èr wèi zuòzhě zhǐchū fùxí de zhòngyàoxìng. Liǎng wèi zuòzhě dōu zhīchí zhǔdòng xuéxí.", "meaning": "O primeiro autor destaca a prática. O segundo aponta a importância da revisão. Ambos apoiam aprendizagem ativa.", "wrong": "两位作者都支持主动学习 significa ambos são contrários à aprendizagem ativa.", "task": "Escreva dois pontos de vista curtos e uma síntese que atribua cada ideia a uma fonte."}, {"id": "course-chines-36", "title": "Projeto final: proposta e apresentação", "stage": 2, "module": "3 · Avançado", "language": true, "extension": true, "theory": "Planeje necessidade, solução, execução e verificação. Prepare texto e apresentação oral e revise tempo, aspecto, classificadores e estrutura dos complementos. Escolha formas que consegue explicar e consulte referências para dúvidas. Registre também o que mudaria depois de ouvir sua própria apresentação.", "phrase": "我建议每周组织一次学习小组。如果我们交流意见，就能互相学习。我们每个月检查一次结果。", "reading": "Wǒ jiànyì měi zhōu zǔzhī yí cì xuéxí xiǎozǔ. Rúguǒ wǒmen jiāoliú yìjiàn, jiù néng hùxiāng xuéxí. Wǒmen měi ge yuè jiǎnchá yí cì jiéguǒ.", "meaning": "Sugiro organizar um grupo de estudo semanal. Se trocarmos opiniões, poderemos aprender uns com os outros. Conferiremos os resultados uma vez por mês.", "wrong": "我们每个月检查一次结果 significa que os resultados nunca serão conferidos.", "task": "Prepare uma proposta de oito a doze frases e uma fala de dois minutos com autoavaliação."}], "redes": [{"id": "course-redes-lab-1", "title": "Laboratório: construir uma pequena rede", "source": "p10-1", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Uma rede funcional exige meio físico, endereçamento coerente e testes de comunicação. Simule o ambiente antes de alterar uma rede real. Separe a ligação entre dispositivos do caminho até a internet e registre o propósito de cada equipamento.", "task": "Em um simulador ou no papel, conecte dois computadores e um switch. Atribua 192.168.50.10/24 e .11/24. Planeje testes, simule a troca de um endereço e documente o resultado.", "answer": "Os dois hosts pertencem à mesma sub-rede. Para comunicação local entre eles, não é necessário gateway. Depois de mudar um host para outra sub-rede, será necessário um caminho de camada 3 adequado. Registre hipótese, teste e evidência, não apenas funciona ou não funciona."}}, {"id": "course-redes-lab-2", "title": "VLSM e plano de endereçamento", "source": "p10-6", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "VLSM permite usar prefixos diferentes conforme o tamanho de cada segmento. Calcule blocos pela necessidade, reserve expansão e respeite limites de rede. Uma tabela de endereços facilita diagnosticar sobreposição e gateway incorreto.", "task": "Divida 192.168.40.0/24 para grupos de 50, 25 e 10 hosts. Liste prefixo, rede, faixa convencional de hosts e broadcast de cada grupo.", "answer": "Uma solução usa .0/26 para 50 hosts, .64/27 para 25 e .96/28 para 10. As faixas são .1–.62, .65–.94 e .97–.110, com broadcasts .63, .95 e .111. Há espaço restante para expansão. Não confunda tamanho do bloco com quantidade de hosts utilizáveis."}}, {"id": "course-redes-lab-3", "title": "IPv6: prefixos e descoberta de vizinhos", "source": "p10-5", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "IPv6 não usa ARP nem broadcast IPv4. Neighbor Discovery participa da descoberta de vizinhos e roteadores por ICMPv6. Endereços link-local têm escopo de enlace. Prefixo, rota e resolução de nomes continuam sendo verificações distintas.", "task": "Planeje dois segmentos de documentação usando 2001:db8:10:1::/64 e 2001:db8:10:2::/64. Identifique o caminho entre eles e descreva como testaria vizinhos e conectividade em simulador.", "answer": "Os prefixos diferem e a comunicação entre segmentos depende de roteamento. O bloco 2001:db8::/32 é reservado para documentação e não representa um endereço público para implantação. Não bloqueie todo ICMPv6 sem considerar funções essenciais."}}, {"id": "course-redes-lab-4", "title": "DHCP: concessão e reservas", "source": "p10-8", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "DHCP distribui parâmetros como endereço, máscara, gateway e DNS. Reservas e exclusões ajudam a evitar conflitos, mas não substituem inventário e controle. Um cliente com endereço válido ainda pode ter gateway ou DNS incorreto.", "task": "Projete uma faixa de 192.168.60.100 a .150 em uma rede /24, excluindo o gateway .1 e equipamentos com endereço fixo. Simule um cliente sem concessão e escreva uma árvore de diagnóstico.", "answer": "Confira enlace, acesso ao servidor ou relay e disponibilidade da faixa. Compare parâmetros recebidos, tempo de concessão e registros do serviço. Não atribua endereços aleatórios numa rede em produção para tentar resolver o problema."}}, {"id": "course-redes-lab-5", "title": "DNS: nome, servidor e resposta", "source": "p10-8", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "DNS envolve perguntas, respostas e cache. Um servidor recursivo consulta em nome do cliente; uma resposta autoritativa tem outra função. A falha em abrir um site pode estar no DNS ou em etapas posteriores, portanto registre cada teste separadamente.", "task": "Crie uma tabela fictícia com nome, endereço esperado, servidor consultado e resultado. Planeje consultas com nslookup e compare uma resposta correta com nome inexistente e falha de conexão ao servidor.", "answer": "Nome inexistente e servidor indisponível são evidências diferentes. Validar uma resposta DNS não prova que o serviço HTTPS funciona. Registre a configuração antes de mudar qualquer parâmetro e use apenas sistemas próprios ou autorizados."}}, {"id": "course-redes-lab-6", "title": "VLAN e trunk em um cenário aplicado", "source": "p10-11", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Uma VLAN define segmentação de camada 2. Um trunk pode transportar várias VLANs com marcação apropriada; uma porta de acesso associa o dispositivo ao segmento configurado. A comunicação entre VLANs requer função de camada 3 e política de acesso.", "task": "Desenhe dois switches com VLANs 10 e 20. Documente portas de acesso, trunk, VLANs permitidas e gateways. Simule uma VLAN ausente no trunk e descreva o impacto.", "answer": "Dispositivos da VLAN afetada podem perder comunicação entre os switches, embora portas locais continuem funcionando. Compare as duas extremidades do enlace. Um trunk não autoriza por si só a comunicação entre VLANs nem substitui firewall."}}, {"id": "course-redes-lab-7", "title": "Roteamento estático e prefixo mais específico", "source": "p10-10", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "A escolha de rota considera a correspondência de prefixo mais longa antes de outros critérios entre rotas comparáveis. Uma rota padrão atende destinos sem rota mais específica. É preciso também existir caminho de retorno.", "task": "Monte uma tabela com 0.0.0.0/0 por A, 10.0.0.0/8 por B e 10.2.0.0/16 por C. Determine caminhos para 10.2.3.4, 10.9.0.1 e 192.0.2.1 e planeje retorno.", "answer": "As escolhas são C, B e A, respectivamente. Uma saída adequada não garante retorno. Use 192.0.2.0/24 apenas como rede de documentação no exercício. Registre origem e destino de cada teste."}}, {"id": "course-redes-lab-8", "title": "Roteamento dinâmico: vizinhança e convergência", "source": "p10-10", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Um protocolo dinâmico distribui informações e recalcula caminhos quando a topologia muda. OSPF usa conceitos como vizinhança, área e custo. A convergência não é instantânea e depende do projeto e das condições da rede.", "task": "Desenhe três roteadores em triângulo e atribua custos fictícios aos enlaces. Compare o caminho preferido antes e depois de uma falha. Documente o que observaria em vizinhos e tabela de rotas, sem configurar produção.", "answer": "O caminho de menor custo disponível depende das somas e da topologia. Após a falha, os dispositivos precisam detectar e propagar a mudança. Ter um enlace alternativo não garante capacidade suficiente ou convergência adequada."}}, {"id": "course-redes-lab-9", "title": "Projeto de cobertura Wi-Fi", "source": "p10-12", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Cobertura e capacidade são problemas relacionados, mas diferentes. Obstáculos, interferência, bandas e quantidade de clientes influenciam a experiência. A potência do AP não resolve automaticamente o caminho de retorno de um cliente fraco.", "task": "Desenhe uma planta fictícia com três ambientes, número de clientes e obstáculos. Proponha posições de APs, rede de visitantes e um plano de medição antes e depois.", "answer": "Justifique cada posição com observações e teste real autorizado ou simulado. Separe visitantes da rede interna e use proteção compatível atualizada. Não conclua qualidade apenas pelas barras de sinal ou pela velocidade nominal anunciada."}}, {"id": "course-redes-lab-10", "title": "Firewall: matriz de acesso e verificação", "source": "p10-15", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Uma política de acesso deve especificar origem, destino, serviço, direção e justificativa. A ordem das regras e o estado das conexões afetam o resultado. Regras amplas demais podem funcionar no teste e ainda violar o objetivo do projeto.", "task": "Crie uma matriz que permita HTTPS externo a visitantes e bloqueie acesso deles a redes internas. Defina quatro testes permitidos e quatro negados e o registro esperado.", "answer": "Teste os dois lados da política: permitir o necessário e negar o restante. Confira IPv4 e IPv6 se ambos existirem. Não aplique bloqueios em produção sem autorização, plano de retorno e acesso de administração preservado."}}, {"id": "course-redes-lab-11", "title": "Análise de tráfego em laboratório", "source": "p10-9", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Uma captura representa tráfego de uma interface e período específicos, não de toda a rede automaticamente. Observe origem, destino, protocolo e sequência. Dados capturados podem conter informações sensíveis; use tráfego sintético e ambiente próprio.", "task": "Planeje uma captura autorizada ou use uma captura didática pública. Identifique uma consulta DNS e uma conexão TCP e escreva o que é observado e o que é apenas hipótese.", "answer": "Pacotes permitem observar eventos do ponto de captura. Tráfego cifrado limita a leitura do conteúdo. Não faça captura em rede de terceiros e não publique endereços, cookies ou outros dados privados de uma captura real."}}, {"id": "course-redes-lab-12", "title": "Projeto integrado de rede e recuperação", "source": "p10-18", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Integre capacidade, segurança, disponibilidade e documentação. Um projeto precisa de critérios de aceitação e plano de falha, não somente desenho de equipamentos. A validação deve incluir retorno, restauração e comunicação de impacto.", "task": "Entregue planta lógica, endereços, VLANs, serviços, matriz de acesso, oito testes e um plano de recuperação para uma escola fictícia de 60 dispositivos.", "answer": "A entrega é aceita quando um terceiro entende o desenho, reproduz os testes no laboratório e identifica como reagir a falhas. Justifique escolhas e limites, registre resultados e revise o projeto após uma falha simulada."}}], "hardware": [{"id": "course-hardware-lab-1", "title": "Bancada segura e plano de intervenção", "source": "p14-8", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Planejamento evita danos e perda de dados. Uma intervenção começa por identificação, autorização e proteção das informações. Desligamento, desconexão de energia e medidas contra descarga eletrostática devem seguir os manuais. Fonte de alimentação não deve ser aberta pelo aluno.", "task": "Monte uma lista de ferramentas, riscos, autorizações e etapas para uma limpeza preventiva fictícia. Indique quando interromper e procurar um técnico qualificado.", "answer": "Inclua backup verificado, identificação do equipamento, manuais, energia desconectada e cuidados ESD. Não faça intervenção energizada nem abra fonte. A atividade pode ser concluída por planejamento, sem desmontagem real."}}, {"id": "course-hardware-lab-2", "title": "Compatibilidade antes da montagem", "source": "p14-3", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Socket, chipset, BIOS, memória, gabinete e alimentação precisam ser compatíveis. Compatibilidade física não assegura suporte funcional. Verifique modelos e revisões exatos e mantenha registro das fontes consultadas.", "task": "Crie uma ficha de um PC fictício com CPU, placa-mãe, RAM, SSD, gabinete e fonte. Justifique interfaces, limites e conectores usando manuais dos fabricantes.", "answer": "Confira lista de suporte de CPU e versão mínima de firmware, tipo de RAM, dimensões e orçamento de energia. Evite escolher peças apenas por nomes comerciais semelhantes. Não invente especificações ausentes no manual."}}, {"id": "course-hardware-lab-3", "title": "Resfriamento e montagem planejada", "source": "p14-2", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "O sistema térmico depende de compatibilidade do cooler, fixação, contato e circulação de ar. Temperatura também depende da carga e do ambiente. Um erro de montagem pode causar instabilidade mesmo quando o computador parece ligar.", "task": "Planeje instalação de um cooler compatível com uma CPU fictícia e um teste de temperatura. Registre procedimento do fabricante e critérios para interromper o teste.", "answer": "Não force encaixes ou aplique procedimentos genéricos no lugar do manual. Compare repouso e carga autorizada, observando limites do modelo. A execução física exige experiência ou supervisão; não toque em componentes energizados."}}, {"id": "course-hardware-lab-4", "title": "POST e isolamento de falhas", "source": "p14-9", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Ventoinhas ligadas não comprovam POST concluído. LEDs e códigos devem ser interpretados no manual específico. Uma configuração mínima pode ajudar um técnico a isolar componentes, mas alterações sem método criam novas variáveis.", "task": "Produza uma árvore de diagnóstico para PC sem imagem com monitor ligado. Separe observações externas de verificações internas que exigem técnico e equipamento desligado.", "answer": "Comece por conexão, entrada do monitor e evidências de POST. Registre cada hipótese e teste uma variável por vez. Não presuma defeito da placa-mãe antes de conferir sinais e componentes de forma segura."}}, {"id": "course-hardware-lab-5", "title": "Portas, periféricos e conexões", "source": "p14-7", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Formato do conector não determina todas as funções. Uma porta USB-C pode ter capacidades diferentes conforme o dispositivo, cabo e implementação. Identifique requisitos de energia, dados e vídeo antes de atribuir defeito.", "task": "Compare três periféricos fictícios e seus requisitos. Monte um roteiro para um dispositivo que recebe energia, mas não transfere dados.", "answer": "Confira documentação de portas e cabos, teste com conjunto compatível e observe reconhecimento no sistema. Receber energia não prova suporte a dados ou vídeo. Evite conectar acessórios de origem desconhecida."}}, {"id": "course-hardware-lab-6", "title": "Armazenamento, saúde e preservação", "source": "p14-4", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Sintomas de armazenamento podem envolver dispositivo, conexão, sistema de arquivos ou software. Indicadores de saúde ajudam a investigar, mas não substituem backup. Copiar dados e tentar reparos são operações diferentes e devem seguir uma prioridade definida.", "task": "Crie um roteiro para um computador lento com arquivos importantes. Liste evidências, plano de cópia e pontos em que uma recuperação profissional seria necessária.", "answer": "Preserve dados antes de testes destrutivos ou reinstalação. Não formate para testar e não interprete um único indicador como garantia absoluta de integridade. Se houver falha física suspeita, pare e encaminhe a especialista."}}, {"id": "course-hardware-lab-7", "title": "UEFI e inicialização segura", "source": "p14-5", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "UEFI, ordem de boot, modo de armazenamento e políticas de inicialização participam da partida do sistema. Detectar um SSD não prova que exista carregador de sistema íntegro. Mudanças de firmware devem ser autorizadas e documentadas.", "task": "Analise um caso fictício em que o disco é reconhecido, mas o sistema não inicia. Prepare verificações e um plano de recuperação que preserve dados e proteções.", "answer": "Registre configuração e mensagens exatas. Confira mídia e sistema suportados. Não desative mecanismos de segurança indiscriminadamente nem atualize firmware sem necessidade, arquivo correto e procedimento do fabricante."}}, {"id": "course-hardware-lab-8", "title": "Memória e instabilidade", "source": "p14-2", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Travamentos podem envolver RAM, temperatura, alimentação, driver ou aplicação. Um teste é uma evidência dentro de um conjunto, não um diagnóstico automático completo. A compatibilidade e a configuração da memória precisam ser verificadas no manual.", "task": "Elabore um plano de investigação para falhas intermitentes, indicando observações, teste de memória apropriado e critérios de encaminhamento.", "answer": "Registre frequência, carga e mudanças recentes. Preserve trabalho e faça backup. Testes podem exigir reinicialização; planeje a indisponibilidade. Alterações físicas só com energia desconectada e pessoa qualificada."}}, {"id": "course-hardware-lab-9", "title": "Temperatura e manutenção preventiva", "source": "p14-8", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Poeira, ventilação, carga de trabalho e montagem afetam temperatura. A prevenção deve ser adequada ao ambiente e ao modelo. Um procedimento de limpeza precisa proteger componentes, dados e o técnico e não deve ser confundido com reparo de fonte.", "task": "Monte um plano semestral fictício com inspeção externa, registro térmico, autorização e limpeza prevista conforme manual.", "answer": "Defina o que observar, como registrar e quando intervir. Não use líquidos ou métodos improvisados. Desligue e desconecte antes de intervenções permitidas; não abra a fonte e não toque em partes energizadas."}}, {"id": "course-hardware-lab-10", "title": "Backup e teste de restauração", "source": "p14-10", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Uma cópia que nunca foi testada pode falhar quando necessária. Escolha dados, destino, frequência, retenção e responsável. Proteção contra acesso indevido e capacidade de restauração são partes do mesmo plano.", "task": "Crie um conjunto de arquivos de teste, planeje cópia e restauração para uma pasta separada. Compare quantidade, tamanho e abertura dos arquivos restaurados.", "answer": "A restauração deve preservar os originais e ser verificada. Não execute sobre dados reais sem autorização. Registre o procedimento e o tempo necessário e mantenha cópias apropriadas fora do único equipamento de origem."}}, {"id": "course-hardware-lab-11", "title": "Sistema, drivers e atualização controlada", "source": "p14-11", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Atualizações podem corrigir falhas, mas precisam de origem confiável e plano de retorno. O estado anterior e o modelo exato do equipamento ajudam a investigar incompatibilidades. Não use pacotes aleatórios como tentativa genérica de solução.", "task": "Prepare uma ordem de atualização fictícia com inventário, backup, fonte oficial, sequência de testes e forma de retorno.", "answer": "Verifique necessidade, versão e suporte do fabricante. Teste funções afetadas e registre antes e depois. Evite atualizar tudo simultaneamente quando o objetivo é isolar a causa de um problema."}}, {"id": "course-hardware-lab-12", "title": "Projeto integrado: entrega e aceite", "source": "p14-18", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Uma manutenção só está completa após validar o resultado, registrar mudanças e devolver o equipamento com orientação clara. Critérios de aceite devem se relacionar ao sintoma inicial e ao uso esperado.", "task": "Produza ordem de serviço fictícia, inventário, evidências, plano de montagem ou reparo, backup, oito testes finais e guia de uso para o usuário.", "answer": "Um terceiro deve compreender o problema, as ações e a validação. Remova informações sensíveis da documentação compartilhada e encerre acessos temporários. Diferencie recomendações futuras de trabalho já realizado."}}], "basica": [{"id": "course-basica-lab-1", "title": "Mouse, janelas e acessibilidade", "source": "p11-5", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Clique, duplo clique, arrastar e rolar têm funções diferentes. Janelas podem ser alternadas, minimizadas e fechadas. Recursos de acessibilidade devem ser ajustados às necessidades do usuário, com teste de leitura e navegação.", "task": "Pratique com arquivos de teste: abra duas janelas, alterne entre elas, ajuste tamanho e explore uma opção de acessibilidade reversível.", "answer": "Verifique se consegue ler, localizar controles e desfazer o ajuste. Fechar pode encerrar um aplicativo; minimizar o mantém disponível. Registre os passos sem alterar políticas de um equipamento compartilhado."}}, {"id": "course-basica-lab-2", "title": "Atalhos e produtividade", "source": "p11-5", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Atalhos dependem do sistema e do aplicativo, mas combinações como copiar, colar e desfazer são frequentes. Um atalho deve melhorar uma tarefa concreta, não apenas ser memorizado. Saiba como desfazer antes de experimentar.", "task": "Em um documento de teste, copie um trecho, mova outro e desfaça uma alteração. Compare com os comandos do menu e anote cinco atalhos úteis.", "answer": "Copiar mantém a origem; recortar prepara uma movimentação; desfazer reverte ações suportadas. Confira o resultado e não pratique em documentos importantes ou compartilhados sem autorização."}}, {"id": "course-basica-lab-3", "title": "Pastas, nomes e extensões", "source": "p11-4", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Pasta organiza e arquivo armazena conteúdo. Extensão está relacionada ao formato, mas renomeá-la não converte o arquivo. Nomes claros e estrutura simples ajudam a encontrar versões e evitar sobrescritas.", "task": "Crie uma pasta de estudo com três subpastas e seis arquivos de teste. Defina padrão de nomes, copie uma versão e localize-a por busca.", "answer": "Confirme local, formato e versão antes de abrir ou substituir. Evite nomes ambíguos como final2definitivo. Não apague os originais durante o exercício e não exponha dados privados em nomes compartilhados."}}, {"id": "course-basica-lab-4", "title": "Cópias e organização de versões", "source": "c-office-6", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Salvar uma cópia e manter backup são ações relacionadas, mas exigem destino e verificação. Uma pasta sincronizada pode reproduzir exclusões ou alterações. Planeje como recuperar uma versão anterior e teste com dados fictícios.", "task": "Crie três versões de um documento de teste e uma cópia em destino separado. Restaure uma versão para outra pasta e registre o resultado.", "answer": "Abra os arquivos restaurados e compare o conteúdo. Não conclua que um ícone de sincronização garante recuperação em qualquer cenário. Mantenha o original preservado e identifique claramente cada versão."}}, {"id": "course-basica-lab-5", "title": "Pesquisa segura e análise de páginas", "source": "c-office-4", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Endereço, anúncio, conteúdo e contexto ajudam a avaliar uma página. HTTPS protege a conexão, mas não comprova que a oferta seja verdadeira. Evite downloads de origem desconhecida e confira a página oficial do serviço.", "task": "Compare duas páginas fictícias descritas em sua própria tabela. Registre domínio, objetivo, fonte, sinais de pressão e informações solicitadas.", "answer": "Uma análise deve combinar indícios. Não abra links suspeitos para provar que são perigosos, não informe dados reais no exercício e use a documentação oficial para confirmar procedimentos."}}, {"id": "course-basica-lab-6", "title": "E-mail, anexos e comunicação", "source": "c-office-4", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Uma mensagem clara informa assunto, contexto e ação esperada. Anexos exigem atenção ao destinatário, formato e conteúdo. Receber um arquivo não torna sua origem confiável. Evite enviar informações privadas em exemplos de treinamento.", "task": "Prepare, sem enviar a terceiros, uma mensagem fictícia com assunto, pedido e anexo de teste. Crie uma lista de conferência antes do envio.", "answer": "Confira destinatário, versão do arquivo e se o anexo abre. Não inclua senhas ou documentos pessoais. Suspeitas devem ser verificadas por um canal conhecido, não pelo contato indicado na própria mensagem suspeita."}}, {"id": "course-basica-lab-7", "title": "Documentos com estilos e revisão", "source": "c-office-1", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Estilos organizam títulos e corpo de texto de maneira consistente. Listas, espaçamento e revisão tornam o documento mais legível. A aparência precisa ser conferida no formato exportado, não apenas no editor.", "task": "Produza um documento de duas páginas com título, seções, lista e uma tabela. Revise e exporte em PDF, preservando o arquivo editável.", "answer": "Abra o PDF e confira cortes, ordem e legibilidade. Use estruturas reais de título e listas em vez de simular tudo com espaços. Registre como repetir a exportação após uma mudança."}}, {"id": "course-basica-lab-8", "title": "Planilhas: células e referências", "source": "c-office-2", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Uma célula é identificada por coluna e linha. Fórmulas fazem referência a valores e podem mudar quando copiadas. Referências relativas e absolutas têm comportamentos diferentes e devem ser testadas em uma tabela pequena antes de uso real.", "task": "Monte uma planilha com cinco itens, quantidade, preço e total. Copie a fórmula da primeira linha e confira manualmente dois resultados.", "answer": "O total de cada linha deve usar sua própria quantidade e preço. Observe o que mudou nas referências ao copiar. Identifique moeda e unidade e não use dados financeiros reais neste treinamento."}}, {"id": "course-basica-lab-9", "title": "Planilhas: erros e validação", "source": "c-office-2", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Uma fórmula pode estar sintaticamente válida e ainda calcular o que não se pretendia. Texto no lugar de número, intervalo incompleto e referência errada são causas frequentes. Testes simples com valores conhecidos ajudam a verificar o resultado.", "task": "Crie uma planilha com soma e média de cinco valores de teste. Introduza um erro por vez e documente como identificá-lo e corrigi-lo.", "answer": "Compare com cálculo manual e confira intervalos e tipos de dados. Não esconda um erro apenas para melhorar a aparência. Registre o esperado, o observado e a correção aplicada."}}, {"id": "course-basica-lab-10", "title": "Apresentações legíveis e acessíveis", "source": "c-office-3", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Uma apresentação precisa de propósito, sequência e leitura adequada ao público. Contraste, tamanho de fonte e descrição de imagens ajudam a comunicar. Conteúdo demais num slide dificulta acompanhar a fala.", "task": "Crie cinco slides sobre uma rotina de estudo, com objetivo, três ideias e conclusão. Faça uma apresentação de três minutos e revise a legibilidade.", "answer": "Confira em modo de apresentação, não só no editor. Use texto alternativo quando apropriado e imagens com origem identificada. O apresentador deve explicar, não apenas ler uma parede de texto."}}, {"id": "course-basica-lab-11", "title": "PDF: leitura, busca e exportação", "source": "c-office-1", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "PDF preserva uma apresentação do conteúdo, mas pode conter texto pesquisável ou apenas imagens. Busca, seleção e leitura dependem de como o arquivo foi produzido. Exportar exige verificar resultado e manter o documento editável quando necessário.", "task": "Exporte um documento de teste, localize uma palavra com busca e confira seleção e ordem de leitura. Compare com uma imagem de uma página sem OCR.", "answer": "Um texto que parece legível visualmente nem sempre é pesquisável ou acessível. Verifique a função esperada e não compartilhe documento com informações pessoais no exercício."}}, {"id": "course-basica-lab-12", "title": "Projeto integrado de informática básica", "source": "c-office-6", "extended": true, "module": "Laboratórios e projetos aplicados", "lab": {"goal": "Integre organização de arquivos, escrita, cálculo, apresentação e cópia de segurança. A entrega deve ser compreensível para outra pessoa e possível de atualizar sem reconstruir tudo.", "task": "Entregue uma pasta organizada, documento de duas páginas, planilha de estudo, cinco slides e PDF. Prepare também uma mensagem fictícia e teste a restauração de uma cópia.", "answer": "Use nomes consistentes, dados fictícios e testes de abertura. Confira cálculos manualmente e registre os passos. A qualidade é medida por clareza e possibilidade de reprodução, não pelo número de efeitos visuais."}}], "digitacao": [{"id": "course-digitacao-10", "title": "Precisão em números", "module": "4 · Prática aplicada e precisão", "drill": "2026 2027 10 20 30 45 60 90 120 150 200", "theory": "Copie sequências numéricas sem inverter a ordem. Confira cada grupo antes de aumentar a velocidade. Faça sessões curtas e compare resultados na mesma duração.", "extension": true}, {"id": "course-digitacao-11", "title": "Acentos em frases completas", "module": "4 · Prática aplicada e precisão", "drill": "A revisão diária melhora a atenção, a precisão e a memória.", "theory": "Pratique acentos e cedilha em contexto. Diferencie o acionamento de acento morto da letra final e verifique composição no teclado usado.", "extension": true}, {"id": "course-digitacao-12", "title": "Maiúsculas e nomes próprios", "module": "4 · Prática aplicada e precisão", "drill": "Ana e Pedro estudam Português, Inglês e Informática em São Luís.", "theory": "Use maiúsculas apenas onde o texto pede. Compare Shift e Caps Lock e evite transformar uma troca de modo em vários erros seguidos.", "extension": true}, {"id": "course-digitacao-13", "title": "E-mails e endereços fictícios", "module": "4 · Prática aplicada e precisão", "drill": "contato@example.org suporte@example.com https://example.org/curso", "theory": "Treine símbolos em dados fictícios. Não use e-mails privados nem senhas reais. Observe ponto, barra e arroba e corrija mantendo precisão.", "extension": true}, {"id": "course-digitacao-14", "title": "Pontuação técnica", "module": "4 · Prática aplicada e precisão", "drill": "rede: LAN; IP: 192.0.2.10; teste = (10 + 20) / 2.", "theory": "Pratique pontuação sem executar comandos. O texto é somente um exercício de teclado e não uma configuração de rede ou instrução de sistema.", "extension": true}, {"id": "course-digitacao-15", "title": "Transcrição de parágrafo", "module": "4 · Prática aplicada e precisão", "drill": "Aprender exige observar, praticar, conferir o resultado e tentar novamente. A velocidade deve crescer com a precisão.", "theory": "Leia um pequeno trecho antes de digitá-lo. Evite antecipar palavras que não estão no modelo. Faça pausas entre blocos e observe os erros recorrentes.", "extension": true}, {"id": "course-digitacao-16", "title": "Registro de atendimento", "module": "4 · Prática aplicada e precisão", "drill": "Chamado 102: usuário relata falha ao abrir o documento. Verificar formato, versão e permissões.", "theory": "Treine linguagem de atendimento com dados fictícios. Preserve acentos, números e pontuação para que o registro continue compreensível.", "extension": true}, {"id": "course-digitacao-17", "title": "Dados e alinhamento lógico", "module": "4 · Prática aplicada e precisão", "drill": "Item 01: teclado; quantidade: 12. Item 02: mouse; quantidade: 18.", "theory": "Observe grupos de dados sem perder a posição. Revisar identificadores é tão importante quanto revisar palavras, pois uma inversão muda o registro.", "extension": true}, {"id": "course-digitacao-18", "title": "Avaliação prática e plano de melhora", "module": "4 · Prática aplicada e precisão", "drill": "Hoje comparo precisão e velocidade, identifico dificuldades e planejo o próximo treino com calma.", "theory": "Faça três tentativas na mesma duração, com pausas. Compare a mediana e a precisão e escolha dois grupos de letras ou símbolos para uma semana de treino.", "extension": true}]};
for(const c of STUDY_COURSES){c.lessons.push(...COURSE_EXPANSION[c.id]);if(c.kind==="language")c.lessons.sort((a,b)=>a.stage-b.stage);c.plannedMinutes=({redes:240,hardware:180,basica:120,digitacao:60})[c.id]||120;c.description=c.kind==="language"?"36 aulas do básico ao avançado, com leitura aplicada, atividades de 12 questões e avaliações.":c.description;c.lessons.forEach(l=>l.plannedMinutes=c.plannedMinutes)}
